contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes parameters: an address target to send to, and an amount to send from this test to C.
    // We require this contract has enough balance to fund the deposit amount before sending.
    function run(address payable target, uint amount) public payable {
        require(address(this).balance >= amount);

        // read initial observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to C to trigger fallback (increments depositsCount)
        // Use a top-level state-changing call. This call should succeed (we provide value).
        c.f{value: amount}();

        // After sending, depositsCount should have increased by exactly 1 and C's balance increased by amount.
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now as owner (this contract is the owner of c), call withdraw and sendMoney and withdrawAll
        // Observe whether they revert by try/catch and check effects on balances.
        bool withdrewReverted;
        bool sendMoneyReverted;
        bool withdrawAllReverted;

        // attempt withdraw a portion (amount) - should not revert because caller is owner
        try c.withdraw(amount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // attempt sendMoney to target - use a safe small value (use amount again)
        try c.sendMoney(target, amount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // attempt withdrawAll - should not revert
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Single assert expressing the general rule:
        // 1) The fallback call increased depositsCount by 1 and contract balance by amount.
        // 2) As owner, withdraw/ sendMoney/ withdrawAll must not revert (all false).
        // Note: This is a general relation over inputs and observable state.
        assert(
            afterDeposits == beforeDeposits + 1
            && afterBalance == beforeBalance + amount
            && withdrewReverted == false
            && sendMoneyReverted == false
            && withdrawAllReverted == false
        );
    }

    // Allow this test contract to receive Ether when C sends to it.
    receive() external payable {}
}

