contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: target for sendMoney (must be payable), and amount to send into C to trigger fallback,
    // and withdrawAmount to withdraw afterwards (must be <= amount to avoid insufficient-balance transfer revert)
    function run(address payable target, uint amount, uint withdrawAmount) public payable {
        require(address(this).balance >= amount);
        // observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // trigger fallback by sending Ether with a plain low-level call to c
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        // observe after state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // attempt owner-only calls; since this contract deployed c, it is owner. Use try/catch as top-level statements.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // General rule:
        // 1) fallback increased depositsCount by exactly 1
        // 2) C's balance increased by exactly amount
        // 3) withdrawing up to the deposited amount should not revert (withdraw may still revert if withdrawAmount > afterBalance)
        // To make a general rule that holds for all inputs, require withdrawAmount <= afterBalance and then assert that withdraw did not revert,
        // while also asserting the fallback effects. The require is allowed as a precondition on parameters.
        require(withdrawAmount <= afterBalance);

        assert(
            afterDeposits == beforeDeposits + 1
            && afterBalance == beforeBalance + amount
            && withdrewReverted == false
        );
    }

    receive() external payable {}
}

