contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the property-based test
    // deposit1 and deposit2 are two arbitrary amounts to send to c via fallback
    function run(uint deposit1, uint deposit2) public payable {
        require(true);

        // observe before-values
        uint beforeDeposits = c.depositsCount();
        address beforeOwner = c.owner();
        uint beforeBalance = address(c).balance;

        // First deposit: if nonzero, ensure this contract has funds and perform plain top-level call
        if (deposit1 > 0) {
            require(address(this).balance >= deposit1);
            (bool s1, ) = address(c).call{value: deposit1}("");
            require(s1);
        }

        // Second deposit: similarly
        if (deposit2 > 0) {
            require(address(this).balance >= deposit2);
            (bool s2, ) = address(c).call{value: deposit2}("");
            require(s2);
        }

        // observe after-values
        uint afterDeposits = c.depositsCount();
        address afterOwner = c.owner();
        uint afterBalance = address(c).balance;

        // The general rule:
        // depositsCount increases exactly by the number of successful nonzero-value fallback calls executed above
        // owner remains unchanged, and contract balance increases by the sum of amounts sent.
        uint expectedIncrements = 0;
        if (deposit1 > 0) { expectedIncrements += 1; }
        if (deposit2 > 0) { expectedIncrements += 1; }

        assert(
            afterDeposits == beforeDeposits + expectedIncrements
            && afterOwner == beforeOwner
            && afterBalance == beforeBalance + deposit1 + deposit2
        );
    }

    // allow this test contract to receive Ether
    receive() external payable { }
}

contract InvMutTest {
