contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // _send: Ether amount this test will first send to C via its fallback to ensure C has balance
    // attemptAmount: amount to attempt to withdraw via c.withdraw(attemptAmount)
    // callAsOwner: if true, the test will act as the original deployer/owner by requiring that this contract is the owner; otherwise it will act as a non-owner. Because the checker deploys C fresh with owner = msg.sender (the deployer), and then passes C into this constructor, msg.sender for C's deployment is the account that created C; we cannot change that here. So callAsOwner is only used in the assert to relate observed owner to behavior.
    function run(uint _send, uint attemptAmount, bool callAsOwner) public payable {
        require(address(this).balance >= _send);

        // Fund C by invoking its fallback with empty calldata — top-level state-changing call
        address(c).call{value: _send}("");

        // record balance after funding
        uint balBefore = address(c).balance;
        // read owner from c via public getter
        address recordedOwner = c.owner();

        // Now attempt withdraw(attemptAmount) and capture revert behavior
        bool reverted;
        try c.withdraw(attemptAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // Determine whether this InvMutTest contract is the recorded owner
        bool iAmOwner = (address(this) == recordedOwner);

        // General rule: if the caller is the owner then withdraw must NOT revert and the balance must decrease by exactly attemptAmount (but not below zero, i.e., if attemptAmount > balBefore it will transfer balBefore and set balance to 0);
        // if the caller is NOT the owner then withdraw must revert and the balance must remain unchanged.
        // Because withdraw(uint) uses transfer(payable(msg.sender).transfer(_value)), when owner calls with amount > balBefore the call will revert due to insufficient balance; to capture intended behavior of owner withdrawing up to balance, we express the rule as: owner call succeeds iff attemptAmount <= balBefore, and if it succeeds the new balance equals balBefore - attemptAmount; non-owner calls always revert and balance unchanged.

        assert(iAmOwner
            ? ((attemptAmount <= balBefore && !reverted && balAfter == balBefore - attemptAmount) || (attemptAmount > balBefore && reverted && balAfter == balBefore))
            : (reverted && balAfter == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // _send: amount to fund C first via its fallback; attemptAmount: amount to call withdraw with
    function run(uint _send, uint attemptAmount) public payable {
        require(address(this).balance >= _send);

        // Fund C by invoking its fallback with empty calldata — top-level state-changing call
        c.fallback{value: _send}();

        // Observe balance before withdraw and the recorded owner
        uint balBefore = address(c).balance;
        address recordedOwner = c.owner();

        // Attempt withdraw(attemptAmount) and capture revert behavior
        bool reverted;
        try c.withdraw(attemptAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        bool iAmOwner = (address(this) == recordedOwner);

        // If caller is owner then withdraw succeeds exactly when attemptAmount <= balBefore and reduces balance by attemptAmount; if amount > balBefore the call reverts and balance unchanged.
        // If caller is not owner then withdraw must revert and leave balance unchanged.
        assert(iAmOwner
            ? ((attemptAmount <= balBefore && !reverted && balAfter == balBefore - attemptAmount) || (attemptAmount > balBefore && reverted && balAfter == balBefore))
            : (reverted && balAfter == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes parameters that attempt to perform owner-only actions from this contract (which is NOT the original owner).
    // We check that such calls revert and that contract state and balance remain unchanged when they revert.
    function run(address payable target, uint value, uint sendValue) public payable {
        require(address(this).balance >= sendValue, "insufficient test balance");

        // Observe initial public state
        address ownerBefore = c.owner();
        uint depositsBefore = c.depositsCount();
        uint balanceBefore = address(c).balance;

        // Ensure this contract is not the owner (the deployed C had owner = deployer, which is not this contract).
        // If it were equal, the property is vacuous; require they differ so test is meaningful.
        require(ownerBefore != address(this));

        // Try withdrawAll(): should revert because onlyOwner modifier
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Try withdraw(value): should revert
        bool revertedWithdraw;
        try c.withdraw(value) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Try sendMoney to target with sendValue wei: must revert
        // Ensure we have enough balance to attach value
        bool revertedSend;
        try c.sendMoney(target, sendValue) { revertedSend = false; } catch { revertedSend = true; }

        // After attempted calls, read public state again
        address ownerAfter = c.owner();
        uint depositsAfter = c.depositsCount();
        uint balanceAfter = address(c).balance;

        // General rule: since this contract is not the owner, all three privileged calls must revert; when they revert,
        // the observable public state of c (owner, depositsCount, and its Ether balance) must remain equal to before.
        assert(revertedWithdrawAll && revertedWithdraw && revertedSend
               && ownerBefore == ownerAfter
