    // We do not send Ether from this contract to c in this test because the freshly deployed c
    // has initial balance 0; we allow amount to be arbitrary but checks ensure balance observations are consistent.
    function run(uint amount, address target) public payable {
        require(target != address(0), "avoid zero target");

        // Observe pre-state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();
        address beforeOwner = c.owner();

        // Ensure the caller of c in this run is NOT the owner: the InvMutTest contract deployed c, so owner == address(this).
        // We must ensure we act as a non-owner. Achieve this by using call from this contract but through delegatecall-like pattern is disallowed.
