            // In harness, this contract may have msg.value from run being payable; but we must not read msg.value; require balance >= amount
            require(address(this).balance >= amount, "insufficient test balance");
            (bool sent,) = address(c).call{value: amount}("x");
            // fallback increments depositsCount on any payable call to fallback
            // sent may be true or false depending on gas; ignore for general rule, but state change happens only if call succeeded
        }

