        bool withdrewReverted;
        try c.withdraw(amount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try sendMoney to target
        bool sendReverted;
        try c.sendMoney(target, amount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // Try withdrawAll
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Observe final state
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule to assert:
        // - depositsCount never decreases
        // - balance never increases due to withdraw/send actions (they can only decrease or stay same)
        // - if a call reverted, it must not have changed depositsCount nor increased balance
        // - owner remains unchanged
        assert(
            c.owner() == beforeOwner
            && afterDeposits >= beforeDeposits
            && afterDeposits >= midDeposits
            && afterBalance <= midBalance
            && (withdrewReverted ? (afterDeposits == midDeposits && afterBalance == midBalance) : true)
            && (sendReverted ? (afterDeposits == midDeposits && afterBalance == midBalance) : true)
            && (withdrawAllReverted ? (afterDeposits == midDeposits && afterBalance == midBalance) : true)
        );
    }

