    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // We will try an owner action (should succeed) and a non-owner action simulated by calling via a proxy contract.
    // The test takes parameters: amount to send into c as deposit via fallback, and a callValue for sendMoney.
    // It asserts that when caller is owner (this contract) the calls do not revert and change balances accordingly,
    // whereas when caller is a different address (Proxy) the same calls revert and do not change c's balance or depositsCount.

    // A minimal proxy that forwards a call to c using call; it will be a different msg.sender when calling c.
    contract Proxy {
        fallback() external payable {}
        receive() external payable {}
        function callWithdraw(address _c, uint v) external returns (bool) {
            // call withdraw on C; returns whether succeeded
            (bool ok, ) = _c.call(abi.encodeWithSignature("withdraw(uint256)", v));
            return ok;
        }
        function callWithdrawAll(address _c) external returns (bool) {
            (bool ok, ) = _c.call(abi.encodeWithSignature("withdrawAll()"));
            return ok;
        }
        function callSendMoney(address _c, address target, uint v) external returns (bool) {
            (bool ok, ) = _c.call(abi.encodeWithSignature("sendMoney(address,uint256)", target, v));
            return ok;
        }
        function sendEthTo(address payable to, uint v) external payable {
            (bool s,) = to.call{value: v}("");
            require(s);
        }
    }

    // Single public test function per requirements
    function run(uint depositAmount, uint withdrawAmount, uint sendValue) public payable {
        require(address(this).balance >= depositAmount + 1 wei || depositAmount == 0, "not enough balance for deposit");
        // Deploy a proxy (different caller) funded with small amount so it can attempt calls that may transfer back
        Proxy proxy = new Proxy();
        // Fund proxy with 1 wei so it exists some balance (not necessary but harmless)
        if (msg.value > 0) {
            // allow caller to fund this test contract; forward 1 wei to proxy if available
            if (address(this).balance > 0) {
                (bool s,) = address(proxy).call{value: 1 wei}("");
                // ignore success
            }
        }

        // 1) Owner (this contract) sends depositAmount to c via fallback
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient balance to send deposit");
            // send Ether to c to trigger fallback which increments depositsCount
            (bool s1, ) = address(c).call{value: depositAmount}("");
            require(s1, "owner deposit failed");
        }

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // 2) As owner: try withdraw(withdrawAmount) and sendMoney to proxy address
        bool ownerWithdrawReverted = false;
        try c.withdraw(withdrawAmount) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        bool ownerSendReverted = false;
        try c.sendMoney(address(proxy), sendValue) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // record after owner actions
        uint afterBalanceOwner = address(c).balance;
        uint afterDepositsOwner = c.depositsCount();

        // 3) As non-owner (via proxy) attempt same calls; we will capture whether the low-level call succeeded
        // Proxy calls c; because proxy is not owner, these should fail and not change c's observable state
        bool proxyWithdrawOk = proxy.callWithdraw(address(c), withdrawAmount);
        bool proxyWithdrawAllOk = proxy.callWithdrawAll(address(c));
        bool proxySendOk = proxy.callSendMoney(address(c), address(this), sendValue);

        uint afterBalanceProxy = address(c).balance;
        uint afterDepositsProxy = c.depositsCount();

        // Now assert the general rule:
        // - Owner calls must NOT revert (ownerWithdrawReverted==false and ownerSendReverted==false)
        //   OR, if they do revert, then they didn't change c's balance or depositsCount compared to before owner actions.
        // - Proxy (non-owner) calls must fail (proxy*Ok == false) and must not change c's balance or depositsCount compared to after owner actions.
        assert(
            // owner successful or no state change from owner attempt
            (
                (ownerWithdrawReverted == false && ownerSendReverted == false) ||
                (afterBalanceOwner == beforeBalance && afterDepositsOwner == beforeDeposits)
            )
            // AND proxy calls did not succeed
            && (proxyWithdrawOk == false && proxyWithdrawAllOk == false && proxySendOk == false)
            // AND proxy attempts did not change contract state
            && (afterBalanceProxy == afterBalanceOwner && afterDepositsProxy == afterDepositsOwner)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Minimal proxy deployed from this contract so its calls to c have a different msg.sender
    address proxyAddr;
    constructor() payable {}

