    function deployProxy() internal returns (address) {
        if (proxyAddr != address(0)) return proxyAddr;
        bytes memory code = type(HelperProxy).creationCode;
        address addr;
        assembly {
            addr := create(0, add(code, 0x20), mload(code))
        }
