    // Parameters:
    // - depositAmount: Ether owner sends to c to trigger fallback and increment depositsCount
    // - withdrawAmount: value to attempt withdraw as owner
    // - sendValue: value to attempt sendMoney to proxy
    function run(uint depositAmount, uint withdrawAmount, uint sendValue) public payable {
        // If depositAmount > 0, ensure this contract has enough balance to send that amount
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        address proxy = deployProxy();

        // Owner (this contract) optionally send Ether to c to trigger fallback
        if (depositAmount > 0) {
            (bool s,) = address(c).call{value: depositAmount}("");
            require(s, "deposit failed");
