        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Owner actions: try withdraw and sendMoney, record whether they reverted using try/catch
        bool ownerWithdrawReverted;
        try c.withdraw(withdrawAmount) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        bool ownerSendReverted;
        try c.sendMoney(proxy, sendValue) {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        // Record after owner actions
        uint afterOwnerBalance = address(c).balance;
        uint afterOwnerDeposits = c.depositsCount();

        // Now as non-owner: have the proxy attempt the same calls via low-level calls
        // We call the proxy's functions which will in turn call c; capture success flags
        bool proxyWithdrawOk;
        (proxyWithdrawOk,) = proxy.call(abi.encodeWithSignature("callWithdraw(address,uint256)", address(c), withdrawAmount));

        bool proxyWithdrawAllOk;
        (proxyWithdrawAllOk,) = proxy.call(abi.encodeWithSignature("callWithdrawAll(address)", address(c)));

        bool proxySendOk;
        (proxySendOk,) = proxy.call(abi.encodeWithSignature("callSendMoney(address,address,uint256)", address(c), address(this), sendValue));

        // Record after proxy attempts
        uint afterProxyBalance = address(c).balance;
        uint afterProxyDeposits = c.depositsCount();

        // General invariant to assert:
        // 1) Non-owner attempts (via proxy) must NOT succeed (their low-level calls return false)
        // 2) Non-owner attempts must not change c's observable state (balance and depositsCount)
        // 3) Owner attempts either succeed (no revert) OR if they reverted then they did not change c's observable state
        assert(
            // proxy calls failed
            (proxyWithdrawOk == false && proxyWithdrawAllOk == false && proxySendOk == false)
            // and proxy did not change state
            && (afterProxyBalance == afterOwnerBalance && afterProxyDeposits == afterOwnerDeposits)
            // and owner calls either succeeded or left state unchanged compared to before
            && (
                ((ownerWithdrawReverted == false) && (ownerSendReverted == false))
                || (afterOwnerBalance == beforeBalance && afterOwnerDeposits == beforeDeposits)
            )
        );
    }

    // The helper proxy contract bytecode reference is needed; declare the minimal contract here.
    // This inner contract is for deployment only; it is allowed since it's a separate contract declaration.
}

