    // and the InvMutTest contract is the deployer of that C (per instructions), this contract
    // is the owner in c. So to observe non-owner reverts we need to check that calls from
    // the owner succeed and that malicious values that would cause sendMoney to fail will revert
    // and not change balancesCount when the low-level call returns false.

    // We therefore assert the general invariant: after calling sendMoney with any target and value,
    // if the call returned (i.e., did not revert) then depositsCount is unchanged and address(c).balance
    // decreased by exactly the value sent; if the call reverted, depositsCount and address(c).balance
    // are unchanged.

    // But sendMoney uses onlyOwner and then does low-level call with require(__sent_result100);
    // So for the owner, sendMoney either succeeds and transfers out funds, or reverts and leaves state unchanged.

    // We implement the test by first funding c via its fallback (calling with value), record balances and depositsCount,
    // then calling sendMoney and observing whether it reverted. We then assert the stated invariant.

    function run(address payable target, uint amountToFund, uint sendValue) public payable {
        require(address(this).balance >= amountToFund + 1 wei);
        // Fund c by sending Ether to its fallback
        uint beforeDeposits = c.depositsCount();
        uint beforeCBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Send Ether to c to increase its balance and trigger fallback which increments depositsCount
        // Use a direct call to the contract address to trigger fallback
        (bool fundOk,) = address(c).call{value: amountToFund}("");
        // fallback is payable and increments depositsCount on each such call
        // accept both success and failure of funding (though funding should succeed if amountToFund is small)

        uint midDeposits = c.depositsCount();
        uint midCBal = address(c).balance;
        uint midThisBal = address(this).balance;

        // Now attempt to call sendMoney as the owner (this contract is owner). Capture revert.
        bool reverted;
        try c.sendMoney(target, sendValue) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterCBal = address(c).balance;
        uint afterThisBal = address(this).balance;

        // The general rule asserted below:
        // - depositsCount does not change as a result of sendMoney call (fallback only changes it on direct funding)
        // - If sendMoney succeeded (did not revert) then c.balance decreased by sendValue (or by available balance if transfer used lesser? here it transfers value via call so it will forward sendValue and require success),
        //   so afterCBal == midCBal - sendValue and afterThisBal == midThisBal (because funds go to target, not to this contract).
        // - If sendMoney reverted then balances and depositsCount remain equal to mid values.

        assert(
            (afterDeposits == midDeposits) &&
            (
                (!reverted && afterCBal + sendValue == midCBal) ||
                (reverted && afterCBal == midCBal)
            )
        );
    }

    // allow receiving Ether if target forwards to this contract during tests
    receive() external payable {}
}

