        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Fund c by triggering its fallback (which is payable and increments depositsCount)
        // Use call to send Ether to contract c so fallback executes
        (bool sentToC, ) = address(c).call{value: sendAmount}("");
        require(sentToC, "funding c failed");

        uint afterFundDeposits = c.depositsCount();
        uint afterFundBalance = address(c).balance;

        // Ensure the fallback had its intended observable effects: depositsCount increased by 1 and balance increased by sendAmount
        // If this doesn't hold, the contract is already misbehaving in a way unrelated to owner checks, but we still continue to test access control below.

        // Attempt to withdrawAll as non-owner (this contract is NOT owner of c)
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Attempt to withdraw a specific amount as non-owner
        bool withdrewReverted;
        try c.withdraw(opAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt to sendMoney as non-owner
        bool sendMoneyReverted;
        try c.sendMoney(target, opAmount) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read final observables
        uint finalDeposits = c.depositsCount();
        uint finalBalance = address(c).balance;

        // General rule: since this contract is not the owner of c, at least the owner-restricted actions (withdrawAll, withdraw, sendMoney)
        // must revert; if any did not revert, then c's balance may have decreased accordingly. We assert that either all owner-restricted calls reverted,
        // or, if one succeeded, then the contract's balance or depositsCount reflect that success (i.e., balance decreased or depositsCount unchanged)
        // but more strictly: for non-owner caller, none of the owner-only functions should succeed. Thus we assert they all reverted.
        assert(withdrewAllReverted && withdrewReverted && sendMoneyReverted &&
               // additionally check that the funding behaved as expected: depositsCount increased by exactly 1 and balance increased by sendAmount
               afterFundDeposits == beforeDeposits + 1 && afterFundBalance == beforeBalance + sendAmount &&
               // final state: no change caused by non-owner calls (they reverted) so final values equal post-fund values
               finalDeposits == afterFundDeposits && finalBalance == afterFundBalance);
    }

    // Allow receiving Ether so test can be funded externally
    receive() external payable {}
}

