    // We take an arbitrary caller address by having the test be the caller (this contract).
    // Provide an amount to send as deposit to trigger fallback increment and put ETH into c.
    function run(address payable targetForSend, uint amount) public payable {
        require(true);

        // Ensure this test contract has enough balance to forward amount to c.
        // In the single-transaction checker, address(this) may have some balance; require to be safe.
        require(address(this).balance >= amount);

        // Record before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to c to trigger fallback which increments depositsCount.
        // Use low-level call to c.address with value amount. Since c.fallback is payable it will accept.
        (bool sent, ) = address(c).call{value: amount}("");
        // We don't assert on this send; if it reverts the later logic still must hold for that execution.

        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Now attempt to call withdrawAll from this contract (msg.sender for c will be this contract).
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // After the call, read final observable values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // If withdrawAll succeeded (did not revert) then:
        //  - c's balance must be zero (withdrawAll withdraws entire balance)
        //  - depositsCount must be >= midDeposits (withdrawAll must not decrement depositsCount)
        // Otherwise (if withdrawAll reverted) we assert nothing about balances except that the depositsCount did not decrease compared to midDeposits.
        // We encode this as a single boolean expression below.
        assert(
            (withdrew && afterBalance == 0 && afterDeposits >= midDeposits)
            || (!withdrew && afterDeposits >= midDeposits)
        );
    }

    // Allow receiving ETH so test contract can forward funds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    //   targetReceive: an address to which sendMoney might forward funds (not used here)
    //   value: amount to send to C initially (to create a positive balance)
    //   withdrawAmount: amount to attempt to withdraw from C
    // The test contract is the caller for all c.* calls.
    function run(address payable /*targetReceive*/, uint value, uint withdrawAmount) public payable {
        require(address(this).balance >= value);

        // Record observables before any interaction
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Fund C by invoking its fallback via a plain low-level call through address(c).
        // This is NOT a call on c.*, but it's allowed; however per constraints we must
        // make state-changing calls on c itself top-level. The fallback increments depositsCount
        // and accepts ether. Use top-level low-level call here (it's allowed since not a c.f call).
        (bool funded, ) = address(c).call{value: value}("");
        // We don't require funded because the test must be valid regardless; observables capture result.

        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Attempt to call withdraw(withdrawAmount) on c as this contract (which is the deployer of c and thus owner).
        bool didRevert;
        try c.withdraw(withdrawAmount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint gained = address(this).balance; // absolute balance of this contract after operation

        // We cannot directly observe how much this contract gained without knowing starting balance here,
        // but we can reason using before/after of c.balance and the revert flag.

        // General rule asserted as a single boolean expression:
        // - depositsCount never decreases (afterDeposits >= beforeDeposits)
        // - If withdraw reverted: c.balance and depositsCount are unchanged from mid values
        // - If withdraw succeeded: c.balance decreased by exactly withdrawAmount (unless withdrawAmount > midBalance then it may revert),
        //   and afterBalance + withdrawAmount == midBalance
        assert(
            // depositsCount monotonic non-decrease relative to before
            (afterDeposits >= beforeDeposits)
            &&
            (
                // Case: revert -> no change to mid observables
                (didRevert && afterDeposits == midDeposits && afterBalance == midBalance)
                ||
                // Case: success -> balance decreased by withdrawAmount from midBalance
                (!didRevert && midBalance >= withdrawAmount && afterBalance + withdrawAmount == midBalance)
            )
        );
    }

    receive() external payable {}
}

