contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // Receive to accept Ether forwarded from C during withdraw/sendMoney
    receive() external payable {}

    // single public test function: caller is this contract; inputs choose target, amount, and a flag to pick which function to call
    // op: 0 = withdrawAll(), 1 = withdraw(amount), 2 = sendMoney(target, amount)
    function run(address target, uint256 amount, uint8 op, address caller) public payable {
        require(op <= 2);
        // Prepare: fund C with some Ether so withdraw/sendMoney can succeed if owner calls.
        // We must send Ether from this contract to C using a parameter amountToFund.
        // Use 'amount' as funding amount for simplicity. Ensure this contract has enough balance.
        if (amount > 0) {
            require(address(this).balance >= amount);
            // fund C
            c.f{value: amount}();
        }

        // record before values observable from c
        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        // We will simulate calls coming from either owner (this contract is owner since it deployed C) or an external non-owner.
        // The checker runs run(...) in a single transaction originating from the deployer of InvMutTest; to emulate a non-owner caller,
        // we make the decision based on the 'caller' parameter: if caller == address(this) treat as owner-call (succeeds),
        // otherwise treat as non-owner and expect revert. Since we cannot change msg.sender on calls to c, we use the fact
        // that this InvMutTest is the owner of c (it deployed c), so only address(this) is owner. For the non-owner case we expect revert.

        bool expectRevert = (caller != address(this));
        bool didRevert = false;

        if (op == 0) {
            // withdrawAll()
            try c.withdrawAll() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else if (op == 1) {
            try c.withdraw(amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            // op == 2
            // ensure this contract has enough balance to receive any transfer from C in case of successful sendMoney
            // (no extra checks needed here)
            try c.sendMoney(target, amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        // observe after values
        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        // General rule: if a call was made by a non-owner it must revert and leave both balance and depositsCount unchanged.
        // If call did not revert, it must have been an owner-call (i.e., caller == address(this)).
        // Express as assertion relating expectRevert, didRevert, and observed state.
        assert((expectRevert == true && didRevert == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits) ||
               (expectRevert == false && didRevert == false));
    }
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    receive() external payable {}

    // op: 0 = withdrawAll(), 1 = withdraw(amount), 2 = sendMoney(target, amount)
    // 'callerIsOwner' chooses whether we *expect* the call to be from the owner (true) or a non-owner (false).
    function run(address target, uint256 amount, uint8 op, bool callerIsOwner) public payable {
        require(op <= 2);

        // Fund C with 'amount' so owner calls can succeed when withdrawing/sending.
        if (amount > 0) {
            require(address(this).balance >= amount, "insufficient balance to fund C");
            // send Ether to C using its fallback
            (bool sent,) = address(c).call{value: amount}("");
            require(sent);
        }

        uint256 beforeBalance = address(c).balance;
        uint256 beforeDeposits = c.depositsCount();

        bool didRevert = false;

        // We can only have this contract be the msg.sender on calls to c. If callerIsOwner==false, we
        // still attempt the call from this contract and expect it to revert (since this contract IS owner),
        // so to model non-owner behavior we require that callerIsOwner==true iff this contract is allowed to succeed.
        // That means: when callerIsOwner==true we perform the call and expect success; when false we perform the call
        // but we assert it reverts. To detect revert we use try/catch.

        if (op == 0) {
            try c.withdrawAll() {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else if (op == 1) {
            try c.withdraw(amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        } else {
            try c.sendMoney(target, amount) {
                didRevert = false;
            } catch {
                didRevert = true;
            }
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterDeposits = c.depositsCount();

        // General invariant:
        // If callerIsOwner == false then the call must have reverted and left balance and depositsCount unchanged.
        // If callerIsOwner == true then the call must not have reverted.
        assert((callerIsOwner == false && didRevert == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits) ||
               (callerIsOwner == true && didRevert == false));
    }
}

