contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test with arbitrary caller addresses by making calls from this contract
    // The deployed C's owner is the deployer of C (which in the checker is not this contract),
    // so calls from this contract should be non-owner and therefore revert.
    function run(uint sendAmount, address payable target) public payable {
        require(address(this).balance >= sendAmount, "insufficient test balance");

        // Observe pre-call state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt withdrawAll: should revert for non-owner
        bool r_withdrawAll;
        try c.withdrawAll() {
            r_withdrawAll = false;
        } catch {
            r_withdrawAll = true;
        }

        // Attempt withdraw(sendAmount): should revert for non-owner
        bool r_withdraw;
        try c.withdraw(sendAmount) {
            r_withdraw = false;
        } catch {
            r_withdraw = true;
        }

        // Attempt sendMoney(target, sendAmount) sending no ether from this contract (call uses no value)
        bool r_sendMoney;
        try c.sendMoney(target, sendAmount) {
            r_sendMoney = false;
        } catch {
            r_sendMoney = true;
        }

        // Also attempt to trigger fallback by sending Ether to C from this contract
        // This should NOT revert (fallback has no onlyOwner) and should increment depositsCount and increase balance
        // But we will only use the observed effect to ensure non-owner financial methods didn't change state.
        // Perform the send as a top-level call
        if (sendAmount > 0) {
            // ensure balance available
            (bool s, ) = address(c).call{value: sendAmount}("x");
            // s may be true or false depending on fallback logic; we don't assume revert behavior here
        }

        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: any of the three owner-only operations called from this contract must have reverted,
        // and if they reverted then depositsCount and contract balance are unchanged by those calls.
        // Because fallback may have been invoked by the explicit send above, we allow afterDeposits/afterBalance
        // to reflect only that send; therefore we assert that the only allowed differences are no changes caused
        // by the (reverted) owner-only calls. Concretely: if any owner-only call did NOT revert, that's a violation.
        // Also ensure that if they did revert, depositsCount and balance did not decrease (they may increase only due to our send).

        assert(r_withdrawAll && r_withdraw && r_sendMoney && afterDeposits >= beforeDeposits && afterBalance >= beforeBalance);
    }

    receive() external payable {}
}
